import cv2,numpy as np
z=np.load('source_pixels.npz')['rgb']
for f in range(96):
 im=z[f]; hsv=cv2.cvtColor(im,cv2.COLOR_RGB2HSV)
 for name,lo,hi in [('blue',(95,80,50),(140,255,255)),('red',(0,120,80),(12,255,255)),('white',(0,0,180),(179,55,255))]:
