   x,y,w,h,a=stats[i]
   if a>=8: comps.append((a,round(cents[i][0],1),round(cents[i][1],1),x,y,w,h))
  comps.sort(reverse=True)
  if f%6==0 or f==95: print(f,name,comps[:5])
